"""Build the SPURLABS value proposition document from data/registry.json."""
import json, pathlib, html
R = json.loads(pathlib.Path(__file__).with_name('data').joinpath('registry.json').read_text(encoding='utf-8'))
E = html.escape; T = {t['id']: t for t in R['tools']}; ST = R['stages']; L = {l['id']: l for l in R['layers']}; C = {c['id']: c for c in R['customers']}
FOLDED = [('Opportunity Map', 'Opportunity Map; Delivery and Contractor Intelligence'), ('Generative Concepts', 'Concept Twin; Design and Engineering AI'), ('Costline', 'Excel Cost Modeler; Solar Cost Modelling; Project Economics Database; Should-Cost Model; Groundwork; decommissioning cost engine'), ('Investment Case', 'Abacus'), ('Generative Scheduling', 'Mr. Scheduler; Work Plan Builder'), ('Generative Digital Twin', 'Digital Twin in Action; Schedule 3D; Computer Vision'), ('Risk Analysis', 'Risk Analysis; Bargain (risk allocation)'), ('RealityScan', 'RealityScan; Bench; Yardstick'), ('Outturn Forecast', 'Outturn; Position; Anchor; Calibrate'), ('Lessons Learned', 'Lessons Learned; Lens; Continuum; Needle (cited search); Yard (evidence base)'), ('Stage Gate Assistant', 'Stage Gate Assistant; Charter; Steward; Blueprint; Challenge; First Draft'), ('Alignment Room', 'Alignment Room'), ('Cockpit', 'Project Intelligence Cockpit; Cockpit early warning; Watchtower; Signal; Accelerate'), ('Forensic', 'Forensic; Origin; Reset'), ('Asset Potential', 'AI Full Asset Potential; Sustaining Capex')]
IND_TOOLS = {'dc': ['generative-concepts', 'cost-line', 'generative-twin', 'opportunity-map', 'cockpit'], 'ccgt': ['generative-concepts', 'cost-line', 'investment-case', 'outturn', 'asset-potential'], 'nuclear': ['outturn', 'risk-analysis', 'generative-twin', 'cockpit', 'forensic'], 'wind': ['opportunity-map', 'risk-analysis', 'generative-twin', 'cost-line'], 'solar': ['generative-concepts', 'cost-line', 'investment-case', 'asset-potential'], 'hvdc': ['generative-scheduling', 'risk-analysis', 'cockpit', 'opportunity-map'], 'lng': ['generative-concepts', 'cost-line', 'outturn', 'forensic'], 'oil': ['outturn', 'realityscan', 'generative-twin', 'risk-analysis'], 'fab': ['generative-twin', 'generative-scheduling', 'cost-line', 'cockpit'], 'mine': ['realityscan', 'generative-concepts', 'investment-case', 'risk-analysis'], 'water': ['realityscan', 'outturn', 'cost-line', 'generative-twin'], 'hydro': ['outturn', 'risk-analysis', 'forensic', 'cockpit'], 'bridge': ['outturn', 'cockpit', 'forensic', 'lessons-learned'], 'tower': ['cost-line', 'generative-twin', 'generative-scheduling', 'cockpit'], 'manufacturing': ['generative-scheduling', 'cost-line', 'generative-twin', 'stage-gate'], 'pharma': ['stage-gate', 'generative-twin', 'cost-line', 'lessons-learned']}
nm = lambda ids: ', '.join(T[i]['name'] for i in ids)
o = []
o.append('<header><p class="k">Value proposition / November 2026</p><h1>SPURLABS</h1><p class="lede">AI for every stage of a capital project. Fifteen tools on one enterprise platform, from the first opportunity to the last day of an asset’s life.</p></header>')
o.append('<section><h2>The pitch</h2><p class="line"><b>SPURLABS tests every capital project decision against what comparable completed projects actually achieved, and keeps every stakeholder aligned from the first opportunity to FID and through delivery.</b></p><p>Owners, funders and governments approve capital projects on the project’s own numbers. Only 8.5% of major projects finish on budget and on time (Flyvbjerg and Gardner, <i>How Big Things Get Done</i>, 2023). The decision that sets the outcome is taken at the stage gates and at FID, and it is taken on incomplete evidence, with each party holding part of the truth.</p><p><b>The wedge:</b> pre-FID assurance for owners and funders. Outturn Forecast sets the number from comparable projects, Stage Gate Assistant makes the gate decision complete, and Alignment Room shows where the parties disagree. From the gate, the platform extends to every stage of the lifecycle, one tool at a time.</p></section>')
o.append('<section><h2>Where SPURLABS sits</h2><p>Y Combinator’s real estate and construction portfolio reached 126 companies by July 2026, and the newest cohorts are dominated by AI back-office tools for contractors: estimating, document intelligence, drawing review and permitting (<a href="https://www.marketscale.com/industries/engineering-and-construction/ycs-summer-2026-cohort-floods-construction-and-proptech-with-ai-back-office-tools">MarketScale</a>). Recent examples include ScoutOut (AI estimating for contractors, W26), FlowManual and Alloovium (document intelligence, S26), Capveon (forming public-infrastructure demand for contractors and manufacturers, F26) and Foreman (construction management from first estimate to final invoice, W26) (<a href="https://www.extruct.ai/data-room/ycombinator-companies-w26/">W26</a>, <a href="https://www.extruct.ai/data-room/ycombinator-companies-s26/">S26</a>, <a href="https://www.extruct.ai/data-room/ycombinator-companies-f26/">F26</a>). The owner and funder side of the billion-dollar decision is far less served.</p><table class="wide"><tr><th>Category</th><th>Examples</th><th>What they do</th><th>What SPURLABS adds</th></tr><tr><td>Systems of record</td><td>Oracle Primavera and Aconex, Procore, Hexagon EcoSys, InEight</td><td>Hold the project’s own schedule, cost and documents</td><td>The outside view on those numbers, and decisions across them</td></tr><tr><td>Schedule AI</td><td>nPlan, ALICE Technologies, Nodes &amp; Links</td><td>Forecast or optimize the schedule</td><td>Cost, readiness, governance and stakeholders, not schedule alone</td></tr><tr><td>Reality capture</td><td>Buildots, OpenSpace, Disperse</td><td>Measure progress on site for the contractor</td><td>Progress tied to the approved case and the portfolio</td></tr><tr><td>Document AI</td><td>Document Crunch, Trunk Tools, Datagrid</td><td>Read contracts and documents</td><td>Documents feeding the gate decision and the evidence base</td></tr><tr><td>Recent YC contractor tools</td><td>ScoutOut, FlowManual, Alloovium, Foreman, Capveon</td><td>Estimating, documents and pursuit for contractors and builders</td><td>The owner and funder decision at the gates and at FID</td></tr></table><p><b>The differentiation, in four parts.</b> The outside view from a proprietary evidence base of more than 20,000 completed projects, with their source documents and lessons. The decision layer at stage gates and FID, where the value of a capital project is set. Multiplayer by design: Alignment Room puts owners, contractors, lenders, insurers and regulators on one readiness check. One project record from opportunity to decommissioning, so evidence compounds across projects.</p></section>')
o.append('<section><h2>Why it fits what Y Combinator is asking for</h2><p>YC’s Fall 2026 Requests for Startups frame AI moving into the physical world, including infrastructure, and include a request for multiplayer AI: work tools became more powerful when they became multiplayer, and AI has not yet (<a href="https://explainx.ai/blog/yc-requests-for-startups-fall-2026">summary of the Fall 2026 RFS</a>). Capital projects are the most multiplayer work there is, and Alignment Room is multiplayer by default. Paul Graham’s guidance is to state plainly what the company makes and why the founders are the ones to build it (<a href="https://www.ycombinator.com/howtoapply.html">How to Apply</a>): the application should lead with the pre-FID wedge, the evidence base and the founder’s years inside capital-project decisions.</p></section>')
o.append('<section><h2>Why it matters</h2><p>Only 8.5% of major projects are delivered on budget and on time (Flyvbjerg and Gardner, <i>How Big Things Get Done</i>, 2023). Accenture estimates that AI deployed in an integrated way can save $170M to $290M on a $1B project (<a href="https://www.accenture.com/en/insights/infrastructure-capital-projects/ai-enhanced-capital-project">The AI-enhanced capital project</a>). The value comes from connecting decisions across cost, schedule, risk, contract and delivery, and from evidence that compounds across projects, not from any single tool.</p></section>')
o.append('<section><h2>The story</h2><p>Find the right project. Shape the concept, the cost and the case. Plan the build, generated and linked to the model. Test every number against reality. Decide at each gate and at FID, with every stakeholder aligned. Deliver to the approved case, recover when it slips, and run the asset to its potential.</p><table class="wide"><tr><th>Step</th><th>Tools</th></tr>' + ''.join(f'<tr><td>{k}</td><td>{E(nm([t["id"] for t in R["tools"] if t["step"] == k]))}</td></tr>' for k in ['Find','Shape','Plan','Test','Decide','Align','Deliver','Recover','Operate']) + '</table></section>')
o.append('<section><h2>One platform, three layers of value</h2><div class="g3">' + ''.join(f'<div><h3>{E(l["name"])}</h3><p>{E(l["line"])}</p><p class="t">{E(nm([t["id"] for t in R["tools"] if t["layer"] == l["id"]]))}</p></div>' for l in R['layers']) + '</div><p>Every tool reads and writes one project record, and every figure carries its source. The platform runs in the SPURLABS cloud, the customer’s cloud or on the customer’s own servers, and people approve every output.</p></section>')
o.append('<section><h2>The capital project lifecycle</h2>')
for ph in ['Develop', 'Deliver', 'Operate']:
    o.append(f'<h3 class="ph">{ph}</h3>')
    for s in [s for s in ST if s['phase'] == ph]:
        ts = [t for t in R['tools'] if s['id'] in t['stages']]
        o.append(f'<div class="stage"><p class="sn">{E(s["name"])}</p><p class="sq">{E(s["q"])}</p><table>' + ''.join(f'<tr><td>{E(t["name"])}</td><td>{E(t["stages"][s["id"]])}</td></tr>' for t in ts) + '</table></div>')
o.append('</section><section><h2>The tools</h2>')
for t in R['tools']:
    o.append(f'<div class="tool"><p class="k">{E(L[t["layer"]]["name"])} / {E(t["status"])}</p><h3>{E(t["name"])}</h3><p class="line">{E(t["line"])}</p>' + ''.join(f'<p>{E(p)}</p>' for p in t['desc']) + '<table>' + ''.join(f'<tr><td>{E(f[0])}</td><td>{E(f[1])}</td></tr>' for f in t['features']) + '</table>' + '<p class="meta"><b>Under the hood:</b> ' + E('; '.join(t['how'])) + '.</p>' + f'<p class="meta"><b>Lifecycle:</b> {E(", ".join(s["name"] for s in ST if s["id"] in t["stages"]))}. <b>Who uses it:</b> {E(", ".join(C[c]["name"] for c in t["customers"]))}. <b>Works with:</b> {E(nm(t["connects"]))}.</p><p class="val">{E(t["value"])}</p></div>')
o.append('</section><section><h2>Value for each customer</h2>' + ''.join(f'<div class="tool"><h3>{E(c["name"])}</h3><p class="meta">{E(c["who"])}</p><p class="line">{E(c["value"])}</p><table>' + ''.join(f'<tr><td>{E(T[k]["name"])}</td><td>{E(v)}</td></tr>' for k, v in c['how'].items()) + '</table></div>' for c in R['customers']) + '</section>')
o.append('<section><h2>Industries</h2><table class="wide"><tr><th>Industry</th><th>What the platform answers</th><th>Lead tools</th></tr>' + ''.join(f'<tr><td>{E(i["name"])}</td><td>{E(i["line"])}</td><td>{E(nm(IND_TOOLS[i["id"]]))}</td></tr>' for i in R['industries']) + '</table></section>')
o.append('<section><h2>How the toolkit was consolidated</h2><p>Forty-six named items became fifteen tools. Items that served the same decision became features of one tool, so each tool has a distinct value proposition.</p><table class="wide"><tr><th>Tool</th><th>Brings together</th></tr>' + ''.join(f'<tr><td>{E(a)}</td><td>{E(b)}</td></tr>' for a, b in FOLDED) + '</table></section>')
css = 'body{margin:0;background:#F6F5F1;color:#141414;font-family:Geist,"Helvetica Neue",Arial,sans-serif;font-size:16.5px;line-height:1.6}main{max-width:980px;margin:0 auto;padding:56px 28px 80px}h1{font-size:56px;font-weight:600;letter-spacing:-.03em;margin:0}h2{font-size:30px;font-weight:500;letter-spacing:-.02em;margin:56px 0 16px;padding-top:20px;border-top:1px solid #d8d5cd}h3{font-size:20px;font-weight:600;margin:20px 0 6px}.ph{font-size:22px;margin-top:34px;color:#555}.k{font-family:"Geist Mono",monospace;font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:#77736b;margin:0 0 10px}.lede{font-size:22px;color:#333;max-width:46ch}.g3{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}.g3 .t{font-size:14px;color:#666}table{width:100%;border-collapse:collapse;margin:10px 0;font-size:15px}td,th{text-align:left;vertical-align:top;padding:8px 10px 8px 0;border-top:1px solid #e2dfd8}th{font-family:"Geist Mono",monospace;font-size:11.5px;letter-spacing:.06em;text-transform:uppercase;color:#77736b;font-weight:400}td:first-child{font-weight:600;width:28%}.stage{margin:14px 0 22px}.sn{font-weight:600;font-size:18px;margin:0}.sq{color:#555;margin:2px 0 6px}.tool{margin:30px 0;padding-top:16px;border-top:1px solid #e2dfd8}.line{font-size:19px;color:#222}.meta{font-size:14.5px;color:#555}.val{font-weight:600}a{color:#141414}@media(max-width:760px){.g3{grid-template-columns:1fr}h1{font-size:40px}}'
doc = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover"><title>SPURLABS: value proposition</title><link href="https://fonts.googleapis.com/css2?family=Geist:wght@400;500;600&family=Geist+Mono&display=swap" rel="stylesheet"><style>' + css + '</style></head><body><main>' + ''.join(o) + '</main></body></html>'
out = pathlib.Path('/mnt/user-data/outputs/spurlabs-value-proposition.html'); out.write_text(doc, encoding='utf-8'); print('value proposition', len(doc), 'bytes,', len(R['tools']), 'tools')
